trait Shape {
    fn area(&self) -> f64;
}

// static dispatch, resolved at compile time
fn a<S: Shape>(s: &S) -> f64 { s.area() }

// dynamic dispatch, through a vtable
fn b(s: &dyn Shape) -> f64 { s.area() }

